import java.util.Scanner;

public class ParkingLot {
    private int vno;
    private double hours;
    private double bill;

    public void input() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Vehicle Number (last 4 digits): ");
        vno = sc.nextInt();
        System.out.print("Enter Duration Parked (in hours)   : ");
        hours = sc.nextDouble();
    }

    public void calculate() {
        if (hours <= 1.0) {
            bill = 20.0;
        } else if (hours <= 4.0) {
            bill = 20.0 + ((hours - 1.0) * 10.0);
        } else {
            bill = 20.0 + (3.0 * 10.0) + ((hours - 4.0) * 8.0);
        }
    }

    public void display() {
        System.out.println("\n========================================");
        System.out.println("          PARKING LOT RECEIPT           ");
        System.out.println("========================================");
        System.out.println("Vehicle Number : " + vno);
        System.out.println("Duration Parked: " + hours + " hours");
        System.out.printf("Total Charges  : Rs. %.2f\n", bill);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        ParkingLot slot = new ParkingLot();
        slot.input();
        slot.calculate();
        slot.display();
    }
}
```

