import java.util.Scanner;

public class SelectionSortDescending {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double[] temp = new double[10];

        System.out.println("Enter 10 daily temperature readings in Celsius:");
        for (int i = 0; i < 10; i++) {
            System.out.print("Day [" + (i + 1) + "]: ");
            temp[i] = sc.nextDouble();
        }

        System.out.print("\nOriginal Readings: ");
        for (double t : temp) System.out.printf("%.1f ", t);
        System.out.println();

        // Selection Sort Descending
        int n = temp.length;
        for (int i = 0; i < n - 1; i++) {
            int maxIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (temp[j] > temp[maxIdx]) {
                    maxIdx = j;
                }
            }
            double swap = temp[i];
            temp[i] = temp[maxIdx];
            temp[maxIdx] = swap;
        }

        System.out.print("Sorted (Descending): ");
        for (double t : temp) System.out.printf("%.1f ", t);
        System.out.println();
    }
}
```

