import java.util.Scanner;

public class AutomorphicPrimeChecker {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("--- MENU ---");
        System.out.println("1. Check Automorphic Number");
        System.out.println("2. Check Prime Number");
        System.out.print("Enter choice: ");
        int choice = sc.nextInt();

        System.out.print("Enter number: ");
        int n = sc.nextInt();

        switch (choice) {
            case 1:
                long sq = (long) n * n;
                int temp = n;
                int numDigits = 0;
                while (temp > 0) {
                    numDigits++;
                    temp /= 10;
                }
                long divisor = (long) Math.pow(10, numDigits);
                if (sq % divisor == n) {
                    System.out.println(n + " is an AUTOMORPHIC NUMBER (Square: " + sq + ").");
                } else {
                    System.out.println(n + " is NOT an Automorphic number (Square: " + sq + ").");
                }
                break;

            case 2:
                boolean isPrime = (n > 1);
                for (int i = 2; i <= Math.sqrt(n); i++) {
                    if (n % i == 0) {
                        isPrime = false;
                        break;
                    }
                }
                if (isPrime) {
                    System.out.println(n + " is a PRIME NUMBER.");
                } else {
                    System.out.println(n + " is NOT a Prime number.");
                }
                break;

            default:
                System.out.println("Invalid Menu Choice!");
        }
    }
}
```

