import java.util.Scanner;

public class MatrixRowColSum {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] mat = new int[3][3];

        System.out.println("Enter 9 elements for 3x3 matrix:");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                System.out.print("mat[" + i + "][" + j + "]: ");
                mat[i][j] = sc.nextInt();
            }
        }

        System.out.println("\n--- Matrix with Row Sums ---");
        for (int i = 0; i < 3; i++) {
            int rowSum = 0;
            for (int j = 0; j < 3; j++) {
                System.out.print(mat[i][j] + "\t");
                rowSum += mat[i][j];
            }
            System.out.println("| Row " + (i + 1) + " Sum = " + rowSum);
        }

        System.out.println("----------------------------------------");
        System.out.print("Col Sum:\t");
        for (int j = 0; j < 3; j++) {
            int colSum = 0;
            for (int i = 0; i < 3; i++) {
                colSum += mat[i][j];
            }
            System.out.print(colSum + "\t");
        }
        System.out.println();
    }
}
```

