public class VolumeOverloading {
    public double volume(double s) {
        return Math.pow(s, 3);
    }

    public double volume(double r, double h) {
        return (22.0 / 7.0) * Math.pow(r, 2) * h;
    }

    public double volume(double l, double b, double h) {
        return l * b * h;
    }

    public static void main(String[] args) {
        VolumeOverloading geo = new VolumeOverloading();
        System.out.printf("Volume of Cube (s=4.0)          : %.2f cubic units\n", geo.volume(4.0));
